SELECT PARAGRAPH_NO, ORG_VALUE, MOD_VALUE,
       INPUT_DATETIME AS CHANGED_AT, INPUT_USER AS CHANGED_USER
  FROM wo_doc_change_log
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND INPUT_DATETIME >= #{fromAt}
   AND INPUT_DATETIME <= #{toAt}
   AND DEL_DATETIME IS NULL
 ORDER BY LOG_SEQ DESC
 FETCH FIRST #{limit} ROWS ONLY

SELECT PARAGRAPH_NO, ORG_VALUE
  FROM wo_doc_change_log
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND INPUT_DATETIME > #{afterAt}
   AND DEL_DATETIME IS NULL
 ORDER BY LOG_SEQ ASC
